(function () {
  const $ = id => document.getElementById(id);
  const FIELDS = ['number', 'dates', 'supplier', 'customer', 'goods', 'amounts'];
  const FIELD_NAMES = { number: 'Number', dates: 'Dates', supplier: 'Supplier', customer: 'Customer', goods: 'Goods', amounts: 'Amounts' };
  const ACTION_TAGS = {
    bluff: '🎭 bluffing', deflect: '↪️ deflecting', partial_admit: '😬 partial admission',
    produce_document: '📄 produces a document', misquote_rule: '📕 quoting "the rules"',
    stall: '⏳ stalling', confess: '💧 confessing'
  };
  let data = null, player = { name: 'Auditor' }, sources = {}, S = null, submitted = false, practice = false, closeArmed = null;

  const style = document.createElement('style');
  style.textContent = `
  .inv-head{display:flex;justify-content:space-between;align-items:baseline;border-bottom:2px solid #1d1a14;padding-bottom:8px;margin-bottom:10px;gap:10px;flex-wrap:wrap}
  .inv-head b{font-family:'Merriweather',serif;font-size:17px}
  .inv-note{font-style:italic;font-size:13px;margin:0 0 10px;color:#4a4436}
  .inv-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
  .fblock{padding:8px 10px;border-radius:4px;cursor:pointer;border:1px solid transparent;transition:background .15s,border-color .15s,transform .1s}
  .fblock:hover{background:rgba(0,0,0,.05)}
  .fblock.sel{border-color:#9c7a22;background:rgba(224,180,76,.22)}
  .fblock.wide{grid-column:1/-1}
  .fblock.caught{background:rgba(127,183,126,.3);outline:1px dashed #3f7a3e}
  .fblock small{display:block;text-transform:uppercase;letter-spacing:1px;font-size:11px;color:#6b6352;font-weight:600}
  .fblock .val{white-space:pre-wrap;font-family:'IBM Plex Sans',sans-serif}
  .fblock .stamp{float:right;font-size:11px;font-weight:700}
  .dialogue p.sys{background:transparent;color:var(--muted);font-size:13px;font-style:italic;padding:2px 4px}
  .dialogue p.good{border-left:3px solid var(--good)}
  .dialogue p.bad{border-left:3px solid var(--bad)}
  .tag{display:inline-block;font-size:11px;color:var(--accent);border:1px solid rgba(224,180,76,.4);border-radius:4px;padding:0 6px;margin-left:6px}
  .cite{display:block;font-size:12px;color:var(--muted);margin-top:4px}
  .rule-card .src{font-size:12px;color:var(--muted);margin-top:8px}
  .lb{margin-top:16px}.lb li{display:flex;justify-content:space-between;gap:10px}
  .end-actions{display:flex;flex-direction:column;gap:10px;align-items:stretch}
  @media (max-width:760px){.inv-grid{grid-template-columns:1fr}}`;
  document.head.appendChild(style);

  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const show = id => ['start-screen', 'play-screen', 'end-screen'].forEach(s => $(s).classList.toggle('hidden', s !== id));
  const sc = () => Object.assign({ correctFlag: 100, falseFlag: 60, unusedToken: 20, winAccuracy: 0.7 }, data.scoring || {});
  const winAcc = () => { const w = Number(sc().winAccuracy); return w > 1 ? w / 100 : w; };
  const invoice = () => data.invoices[S.inv];
  const fieldOf = (inv, type) => (inv.fields || []).find(f => f.field === type);
  const ruleById = id => (data.rules || []).find(r => r.id === id);
  const ruleFor = type => (data.rules || []).find(r => r.id === type || r.id === 'p-' + type || r.source === 'p-' + type) || (data.rules || [])[FIELDS.indexOf(type)];
  const flagFor = (invId, fid) => S.flags.find(f => f.invId === invId && f.fieldId === fid);
  const totalFlaws = () => data.invoices.reduce((n, inv) => n + inv.fields.filter(f => f.flaw).length, 0);

  function citeText(srcId) {
    const s = sources[srcId];
    return s ? `📖 ${s.heading}${s.loc ? ' · ' + s.loc : ''}` : '';
  }

  function feedback(msg, kind) {
    const fb = $('feedback');
    fb.className = 'feedback' + (kind ? ' ' + kind : '');
    fb.textContent = msg;
  }

  function say(who, text, opts = {}) {
    const p = document.createElement('p');
    p.className = (who === 'you' ? 'you' : who === 'sys' ? 'sys' : '') + (opts.kind ? ' ' + opts.kind : '');
    let html = who === 'victor' ? `<b>Victor:</b> ${esc(text)}` : who === 'you' ? `<b>${esc(player.name || 'You')}:</b> ${esc(text)}` : esc(text);
    if (opts.tag) html += `<span class="tag">${esc(opts.tag)}</span>`;
    (opts.cites || []).forEach(c => { if (c) html += `<span class="cite">${esc(c)}</span>`; });
    p.innerHTML = html;
    $('dialogue').appendChild(p);
    $('dialogue').scrollTop = $('dialogue').scrollHeight;
  }

  function currentScore() {
    const c = sc();
    return S.flags.reduce((n, f) => n + (f.correct ? c.correctFlag : -Math.abs(c.falseFlag)), 0);
  }

  function renderHud() {
    $('tokens').textContent = S.tokens;
    $('flags-count').textContent = S.flags.length;
    $('score').textContent = currentScore();
  }

  function renderTabs() {
    const box = $('exhibit-tabs');
    box.innerHTML = '';
    data.invoices.forEach((inv, i) => {
      const b = document.createElement('button');
      b.className = 'btn';
      b.setAttribute('aria-pressed', String(i === S.inv));
      const n = S.flags.filter(f => f.invId === inv.id).length;
      b.textContent = (inv.exhibit || 'Exhibit ' + (i + 1)) + (n ? ` · ${n}🚩` : '');
      b.onclick = () => { S.inv = i; S.field = null; hideRules(); renderAll(); feedback(''); };
      box.appendChild(b);
    });
  }

  function renderInvoice() {
    const inv = invoice();
    const box = $('invoice');
    box.style.opacity = 0;
    const order = ['number', 'dates', 'supplier', 'customer', 'goods', 'amounts'];
    let html = `<div class="inv-head"><b>INVOICE</b><span>${esc(inv.exhibit || inv.id)}</span></div>`;
    if (inv.note) html += `<p class="inv-note">${esc(inv.note)}</p>`;
    html += '<div class="inv-grid">';
    order.forEach(type => {
      const f = fieldOf(inv, type);
      if (!f) return;
      const fl = flagFor(inv.id, f.id);
      const cls = ['fblock', type === 'goods' || type === 'amounts' ? 'wide' : '', S.field === type ? 'sel' : '', fl ? (fl.correct ? 'caught' : 'flagged') : ''].join(' ');
      const stamp = fl ? `<span class="stamp">${fl.correct ? '✔ CAUGHT' : '✘ DISPUTED'}</span>` : '';
      html += `<div class="${cls}" data-f="${type}" tabindex="0" role="button">${stamp}<small>${esc(f.label || FIELD_NAMES[type])}</small><div class="val">${esc(f.value)}</div></div>`;
    });
    box.innerHTML = html + '</div>';
    box.querySelectorAll('.fblock').forEach(el => {
      const pick = () => selectField(el.dataset.f);
      el.onclick = pick;
      el.onkeydown = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick(); } };
    });
    requestAnimationFrame(() => { box.style.opacity = 1; });
  }

  function renderFieldButtons() {
    const box = $('field-buttons');
    box.innerHTML = '';
    FIELDS.forEach(type => {
      const b = document.createElement('button');
      b.className = 'btn';
      b.textContent = FIELD_NAMES[type];
      b.setAttribute('aria-pressed', String(S.field === type));
      b.disabled = !fieldOf(invoice(), type);
      b.onclick = () => selectField(type);
      box.appendChild(b);
    });
  }

  function renderRuleCard() {
    const card = $('rule-card');
    if (!S.field) {
      card.innerHTML = '<h3>Rulebook</h3><p class="muted" style="margin:0">Select a field on the invoice to open the matching page of the rulebook.</p>';
      return;
    }
    const r = ruleFor(S.field);
    if (!r) { card.innerHTML = '<h3>Rulebook</h3><p class="muted">No rule card for this field.</p>'; return; }
    const src = sources[r.source];
    card.innerHTML = `<h3>Rulebook</h3><h2 style="font-size:16px">${esc(r.name)}</h2><p style="margin:0">${esc(r.text || (src && src.text))}</p>` +
      (src ? `<div class="src">📖 ${esc(src.heading)}${src.loc ? ' · ' + esc(src.loc) : ''}</div>` : '');
  }

  function renderActions() {
    const f = S.field && fieldOf(invoice(), S.field);
    const flagged = f && flagFor(invoice().id, f.id);
    $('ask-btn').disabled = !f || S.busy || S.tokens <= 0;
    $('flag-btn').disabled = !f || S.busy || !!flagged;
    $('ask-btn').textContent = S.busy ? 'Victor is answering…' : 'Ask (1 token)';
  }

  function renderAll() { renderHud(); renderTabs(); renderInvoice(); renderFieldButtons(); renderRuleCard(); renderActions(); }

  function selectField(type) {
    if (!fieldOf(invoice(), type)) return;
    S.field = type;
    hideRules();
    renderInvoice(); renderFieldButtons(); renderRuleCard(); renderActions();
  }

  function hideRules() { $('rule-select').classList.add('hidden'); $('rule-select').innerHTML = ''; }

  function setMood(text) { $('suspect-mood').textContent = text ? '🕴️ ' + text : ''; }

  async function ask() {
    const inv = invoice(), f = fieldOf(inv, S.field);
    if (!f || S.busy || S.tokens <= 0) return;
    S.busy = true; S.tokens--;
    renderHud(); renderActions();
    const q = `About ${inv.exhibit || inv.id}, the ${f.label || FIELD_NAMES[f.field]} field ("${f.value}"): explain why this is in order.`;
    say('you', q);
    S.history.push({ role: 'player', text: q });
    const state = {
      invoice: inv.id, exhibit: inv.exhibit, field: f.field, fieldId: f.id, label: f.label, value: f.value,
      tokensLeft: S.tokens, flagsPlaced: S.flags.length, caught: S.flags.filter(x => x.correct).length
    };
    try {
      const r = await GameStudio.askAI({ messages: S.history.slice(-6), state });
      const text = (r && r.say) || '…He adjusts his cufflinks and says nothing.';
      const cites = ((r && r.quotes) || []).map(qt => `📖 ${qt.heading || ''}${qt.loc ? ' · ' + qt.loc : ''}`);
      say('victor', text, { tag: r && ACTION_TAGS[r.action], cites });
      S.history.push({ role: 'ai', text });
      if (r && r.action === 'produce_document') say('sys', 'He slides a "corrected" copy across the table. Compare it with the exhibit before trusting it.');
      if (r && r.action === 'misquote_rule') say('sys', 'Check his version of the rule against the rulebook card.');
      if (r && r.action === 'confess') setMood(r.mood || 'Shoulders sagging. He has run out of stories.');
      else setMood(r && r.mood);
      feedback(S.tokens > 0 ? `${S.tokens} question${S.tokens === 1 ? '' : 's'} left.` : 'Out of questions. Victor reaches for his coat. Place your final flags and file the report.', S.tokens > 0 ? '' : 'bad');
    } catch (e) {
      S.tokens++;
      S.history.pop();
      say('sys', 'Victor glances at the rain and does not answer. (Connection issue: your token was returned.)');
      feedback('Could not reach Victor. Try again.', 'bad');
    }
    S.busy = false;
    renderHud(); renderActions();
  }

  function openRules() {
    const f = S.field && fieldOf(invoice(), S.field);
    if (!f) return;
    const box = $('rule-select');
    if (!box.classList.contains('hidden')) { hideRules(); return; }
    box.innerHTML = '<div class="muted" style="width:100%;font-size:13px">Which mandatory mention does this field breach?</div>';
    (data.rules || []).forEach(r => {
      const b = document.createElement('button');
      b.className = 'btn';
      b.textContent = r.name;
      b.onclick = () => flag(f, r);
      box.appendChild(b);
    });
    const cancel = document.createElement('button');
    cancel.className = 'btn';
    cancel.textContent = 'Cancel';
    cancel.onclick = hideRules;
    box.appendChild(cancel);
    box.classList.remove('hidden');
  }

  function flag(f, rule) {
    const inv = invoice();
    if (flagFor(inv.id, f.id)) return;
    const correct = f.flaw === rule.id;
    S.flags.push({ invId: inv.id, exhibit: inv.exhibit || inv.id, fieldId: f.id, label: f.label || FIELD_NAMES[f.field], ruleId: rule.id, ruleName: rule.name, correct });
    hideRules();
    const c = sc();
    say('you', `I'm flagging the ${f.label || FIELD_NAMES[f.field]} on ${inv.exhibit || inv.id}: it breaches "${rule.name}".`);
    if (correct) {
      say('victor', `…Fine. ${f.answer || 'You have me there.'}`, { kind: 'good', tag: '💧 cracks', cites: [citeText(f.source || rule.source)] });
      feedback(`✔ Correct flag: ${rule.name}. +${c.correctFlag}`, 'good');
      setMood('A bead of sweat. The smile has slipped.');
    } else {
      const why = f.flaw ? 'There is something off here, but not under that rule.' : 'This field meets the requirement.';
      say('victor', `With respect, auditor, that is simply not what the rule says. ${why}`, { kind: 'bad', tag: '🧥 alibi grows', cites: [citeText(rule.source)] });
      feedback(`✘ False accusation. −${Math.abs(c.falseFlag)}`, 'bad');
      setMood('Smug. He straightens his tie and checks his watch.');
    }
    S.history.push({ role: 'player', text: `I flag ${f.field} under ${rule.name}. ${correct ? 'Correct.' : 'Incorrect.'}` });
    renderAll();
    if (S.flags.filter(x => x.correct).length === totalFlaws()) {
      say('sys', 'Every flaw is on the table. Victor puts down his umbrella. Filing the report…');
      setTimeout(endGame, 1400);
    }
  }

  function closeCase() {
    if (S.ended) return;
    const btn = $('close-btn');
    if (!closeArmed) {
      btn.textContent = 'Confirm: file report?';
      btn.classList.add('primary');
      closeArmed = setTimeout(() => { closeArmed = null; btn.textContent = 'Close case & file report'; btn.classList.remove('primary'); }, 3000);
      return;
    }
    clearTimeout(closeArmed); closeArmed = null;
    btn.textContent = 'Close case & file report'; btn.classList.remove('primary');
    endGame();
  }

  function li(list, text) { const x = document.createElement('li'); x.textContent = text; $(list).appendChild(x); }

  async function endGame() {
    if (S.ended) return;
    S.ended = true;
    const c = sc();
    const correct = S.flags.filter(f => f.correct).length;
    const wrong = S.flags.length - correct;
    const total = totalFlaws();
    const missed = total - correct;
    const denom = S.flags.length + missed;
    const accuracy = denom ? correct / denom : 0;
    const score = correct * c.correctFlag - wrong * Math.abs(c.falseFlag) + S.tokens * c.unusedToken;
    const endings = data.endings || {};
    let title, summary;
    if (correct === total && wrong === 0) { title = 'Full confession'; summary = endings.full; }
    else if (accuracy >= winAcc()) { title = 'Case closed'; summary = endings.win; }
    else { title = 'He walked into the rain'; summary = endings.lose; }
    $('end-title').textContent = title;
    $('final-score').textContent = score;
    $('final-accuracy').textContent = Math.round(accuracy * 100) + '%';
    ['caught-list', 'missed-list', 'false-list'].forEach(id => { $(id).innerHTML = ''; });
    S.flags.filter(f => f.correct).forEach(f => li('caught-list', `${f.exhibit}: ${f.label} (${f.ruleName})`));
    data.invoices.forEach(inv => inv.fields.forEach(f => {
      const fl = flagFor(inv.id, f.id);
      if (f.flaw && !(fl && fl.correct)) {
        const r = ruleById(f.flaw);
        li('missed-list', `${inv.exhibit || inv.id}: ${f.label || FIELD_NAMES[f.field]} (${r ? r.name : f.flaw}). ${f.answer || ''}`);
      }
    }));
    S.flags.filter(f => !f.correct).forEach(f => li('false-list', `${f.exhibit}: ${f.label} (accused under ${f.ruleName})`));
    ['caught-list', 'missed-list', 'false-list'].forEach(id => { if (!$(id).children.length) li(id, 'None'); });
    const base = `${summary || ''} You flagged ${correct} of ${total} flaws with ${wrong} false accusation${wrong === 1 ? '' : 's'} and kept ${S.tokens} question${S.tokens === 1 ? '' : 's'} in reserve.`;
    $('end-summary').textContent = base;
    show('end-screen');
    window.scrollTo(0, 0);
    const finishBtn = ensureFinish();
    finishBtn.disabled = true;
    if (practice) {
      $('end-summary').textContent = base + ' Practice round: this score was not submitted.';
      finishBtn.disabled = false;
      return;
    }
    try {
      await GameStudio.submitScore(score, { accuracy: Math.round(accuracy * 1000) / 10, correct, falseFlags: wrong, missed, tokensLeft: S.tokens });
      submitted = true;
    } catch (e) {
      $('end-summary').textContent = base + ' (Your score could not be submitted.)';
    }
    finishBtn.disabled = false;
    showLeaderboard();
  }

  function ensureFinish() {
    let b = $('finish-btn');
    if (b) return b;
    const holder = $('replay-btn').parentNode;
    holder.classList.add('end-actions');
    b = document.createElement('button');
    b.id = 'finish-btn';
    b.className = 'btn primary';
    b.textContent = 'Finish';
    b.onclick = async () => {
      b.disabled = true;
      try { await GameStudio.finish(); } catch (e) { b.disabled = false; $('end-summary').textContent += ' Could not finish right now; please try again.'; }
    };
    holder.insertBefore(b, $('replay-btn'));
    $('replay-btn').classList.remove('primary');
    return b;
  }

  async function showLeaderboard() {
    let box = $('lb-box');
    if (!box) {
      box = document.createElement('div');
      box.id = 'lb-box';
      box.className = 'card lb';
      $('end-screen').appendChild(box);
    }
    box.innerHTML = '<h3>Case board: top auditors</h3><p class="muted">Loading…</p>';
    try {
      const rows = await GameStudio.getLeaderboard();
      box.innerHTML = '<h3>Case board: top auditors</h3>' + (rows && rows.length
        ? '<ol style="margin:0;padding-left:20px">' + rows.map(r => `<li><span>${esc(r.rank)}. ${esc(r.name)}</span><b>${esc(r.score)}</b></li>`).join('') + '</ol>'
        : '<p class="muted">No entries yet.</p>');
    } catch (e) {
      box.innerHTML = '<h3>Case board</h3><p class="muted">Leaderboard unavailable.</p>';
    }
  }

  function newGame() {
    S = { tokens: data.tokens || 8, inv: 0, field: null, flags: [], history: [], busy: false, ended: false };
    $('dialogue').innerHTML = '';
    hideRules();
    feedback('Select a field, then ask about it or flag it.');
    say('sys', data.setting || 'Rain streaks the office window. The case file lies open on the desk.');
    say('victor', `Good evening, ${player.name || 'auditor'}. Every invoice here is in perfect order, I assure you. But please, ask away. I do have a train to catch.`);
    setMood('Calm, polite, one eye on the clock.');
    renderAll();
    show('play-screen');
    window.scrollTo(0, 0);
  }

  $('play-btn').onclick = () => { if (data) newGame(); };
  $('ask-btn').onclick = ask;
  $('flag-btn').onclick = openRules;
  $('close-btn').onclick = closeCase;
  $('replay-btn').onclick = () => {
    if (submitted || !practice) practice = true;
    const lb = $('lb-box'); if (lb) lb.remove();
    newGame();
    feedback('Practice round: your submitted score stays as it is.');
  };

  (async function init() {
    try { await GameStudio.ready(); } catch (e) { }
    $('play-btn').disabled = true;
    try {
      data = await GameStudio.getData();
      if (!data || !Array.isArray(data.invoices) || !data.invoices.length) throw new Error('bad data');
    } catch (e) {
      data = null;
      const p = document.createElement('p');
      p.className = 'feedback bad';
      p.textContent = 'The case file could not be loaded. Please reload the game.';
      $('play-btn').after(p);
      return;
    }
    try { (await GameStudio.getSources() || []).forEach(s => { sources[s.id] = s; }); } catch (e) { }
    try { const p = await GameStudio.getPlayer(); if (p && p.name) player = p; } catch (e) { }
    if (data.intro) document.querySelector('#start-screen .tagline').textContent = data.intro;
    if (data.title) document.querySelector('#start-screen h1').textContent = data.title;
    $('play-btn').disabled = false;
  })();
})();
